/// Cached rows never contain a resolved native kind or MovieClip target.
pub(crate) fn boxhead_graph_anchor_edges_cached_into(
    self, edges: &mut Vec<(AvmString<'gc>, Value<'gc>)>,
) -> Result<usize, &'static str> {
    {
        let read = self.0.borrow();
        if let Some(cached) = &read.anchor_metadata {
            edges.clear();
            edges.extend_from_slice(&cached.edges);
            return Ok(cached.raw_count);
        }
    }
    // Only the explicit preparation walk admits cache entries. A normal
    // checkpoint never begins caching mutable gameplay objects.
    self.boxhead_graph_anchor_edges_into(edges)
}

fn publish_anchor_metadata(self, gc: &Mutation<'gc>, budget: &Rc<MetadataBudget>,
    count: usize, edges: &[(AvmString<'gc>, Value<'gc>)]) -> bool {
    if let Some(cached) = CachedEdges::new(budget, count, edges) {
        // The real write barrier is required even for duplicate owned refs.
        // No AVM code or arena collection runs between validation and here.
        self.0.borrow_mut(gc).anchor_metadata = Some(Box::new(cached));
        return true;
    }
    false
}

/// Optional prewarm: no getter, prototype/native property lookup or clip
/// resolution. Large/unsupported objects stay on the original fresh path.
pub(crate) fn boxhead_graph_anchor_edges_warm_into(
    self, gc: &Mutation<'gc>, budget: &Rc<MetadataBudget>, limit: usize,
    edges: &mut Vec<(AvmString<'gc>, Value<'gc>)>,
) -> Option<(usize, bool)> {
    edges.clear();
    let read = self.0.borrow();
    if !matches!(read.native, NativeObject::None | NativeObject::Array(_))
        || read.watchers.iter().next().is_some() || read.interfaces.is_some() { return None; }
    if let Some(cached) = &read.anchor_metadata {
        if cached.raw_count > limit { return None; }
        edges.extend_from_slice(&cached.edges);
        return Some((cached.raw_count, true));
    }
    let mut count = 0;
    for (key, property) in read.properties.iter() {
        if count == limit { edges.clear(); return None; }
        if property.getter().is_some() || property.setter().is_some() { edges.clear(); return None; }
        count += 1;
        let value = property.data();
        if !key.eq_with_case(b"__proto__", true)
            && matches!(value, Value::Object(_) | Value::MovieClip(_)) { edges.push((key, value)); }
    }
    drop(read);
    let admitted = self.publish_anchor_metadata(gc, budget, count, edges);
    Some((count, admitted))
}

/// Resolve only an original own stored slot for the six fixed XSI roots.
/// This intentionally does not run a getter, watcher, prototype or stage API.
pub(crate) fn boxhead_anchor_metadata_own(self, name: AvmString<'gc>) -> Option<Value<'gc>> {
    let read = self.0.borrow();
    if !matches!(read.native, NativeObject::None | NativeObject::Array(_) | NativeObject::Function(_))
        || read.watchers.iter().next().is_some() || read.interfaces.is_some() { return None; }
    let property = read.properties.get_avm(name, true)?;
    if property.getter().is_some() || property.setter().is_some() { return None; }
    Some(property.data())
}

